package in.aicon.pocket;
import android.app.*;import android.content.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class ReminderScheduleTest {
 Context c; @Before public void setup(){c=RuntimeEnvironment.getApplication();ReminderSchedule.prefs(c).edit().clear().commit();org.robolectric.Shadows.shadowOf((android.app.Application)c).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);}
 @Test public void defaultsOffAndTwoLocalTimes(){assertFalse(ReminderSchedule.prefs(c).getBoolean("enabled",false));assertEquals(510,ReminderSchedule.time(c,0));assertEquals(1230,ReminderSchedule.time(c,1));ReminderSchedule.enabled(c,true);assertEquals(2,Shadows.shadowOf(c.getSystemService(AlarmManager.class)).getScheduledAlarms().size());ReminderSchedule.enabled(c,false);assertEquals(0,Shadows.shadowOf(c.getSystemService(AlarmManager.class)).getScheduledAlarms().size());}
 @Test public void timezoneAndNextDayRollover(){java.util.TimeZone zone=java.util.TimeZone.getTimeZone("Asia/Kolkata");long at=java.time.ZonedDateTime.of(2026,11,11,8,30,0,0,java.time.ZoneId.of("Asia/Kolkata")).toInstant().toEpochMilli();assertEquals(at,ReminderSchedule.next(at-1,510,zone));assertEquals(at+86400000L,ReminderSchedule.next(at,510,zone));assertEquals(java.time.ZonedDateTime.of(2026,11,11,8,30,0,0,java.time.ZoneId.of("Europe/London")).toInstant().toEpochMilli(),ReminderSchedule.next(at,510,java.util.TimeZone.getTimeZone("Europe/London")));}
 @Test public void deniedPermissionDoesNotScheduleAndBootReschedulesOnlyEnabled(){Shadows.shadowOf((android.app.Application)c).denyPermissions(android.Manifest.permission.POST_NOTIFICATIONS);ReminderSchedule.enabled(c,true);assertEquals(0,Shadows.shadowOf(c.getSystemService(AlarmManager.class)).getScheduledAlarms().size());Shadows.shadowOf((android.app.Application)c).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);new ReminderBootReceiver().onReceive(c,new Intent(Intent.ACTION_BOOT_COMPLETED));assertEquals(2,Shadows.shadowOf(c.getSystemService(AlarmManager.class)).getScheduledAlarms().size());ReminderSchedule.enabled(c,false);new ReminderBootReceiver().onReceive(c,new Intent(Intent.ACTION_TIMEZONE_CHANGED));assertEquals(0,Shadows.shadowOf(c.getSystemService(AlarmManager.class)).getScheduledAlarms().size());}
 @Test public void notificationHasNoPrivateAmountsOrPeople(){ReminderSchedule.enabled(c,true);new ReminderReceiver().onReceive(c,new Intent("in.aicon.pocket.REMINDER"));Notification n=Shadows.shadowOf(c.getSystemService(NotificationManager.class)).getNotification(790);assertNotNull(n);assertEquals("Hisab - a quick check-in",n.extras.getString(Notification.EXTRA_TITLE));assertFalse(n.extras.toString().contains("₹"));assertEquals(ReminderSchedule.CHANNEL,n.getChannelId());assertNotNull(c.getSystemService(NotificationManager.class).getNotificationChannel(ReminderSchedule.CHANNEL).getSound());}
}
